// Regrouper le scénario d'ajout d'un produit depuis la liste d'inventaire.
describe('Swag Labs cart', () => {
  // Se connecter avant le test avec la commande partagée.
  beforeEach(() => {
    // Ouvrir une session utilisateur standard sur l'inventaire.
    cy.login();
  });

  // Fermer la session après le test avec la commande partagée.
  afterEach(() => {
    // Déconnecter l'utilisateur après les vérifications.
    cy.logout();
  });

  // Définir le scénario d'ajout au panier depuis la liste.
  it('ajoute un produit depuis la liste et affiche Remove avec un badge à 1', () => {
    // Ajouter le Sauce Labs Backpack depuis la page Inventory.
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Vérifier que le bouton du produit devient Remove.
    cy.get('[data-test="remove-sauce-labs-backpack"]').should('be.visible').and('have.text', 'Remove');
    // Vérifier que le badge du panier affiche un produit.
    cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '1');
  });
});
